from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 12))
    q = draw(st.integers(1, 10))
    alphabet = draw(st.sampled_from(["ab", "abc", "a", "xyz"]))
    s = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    queries = []
    for _ in range(q):
        l = draw(st.integers(1, n))
        r = draw(st.integers(l, n))
        queries.append((l, r))
    lines = [f"{n} {q}", s] + [f"{l} {r}" for l, r in queries]
    return "\n".join(lines) + "\n"

def validate(inp):
    t = inp.split()
    if len(t) < 3:
        return False
    n, q = int(t[0]), int(t[1])
    if not (1 <= n <= 3 * 10**5 and 1 <= q <= 3 * 10**5):
        return False
    s = t[2]
    if len(s) != n or not all('a' <= c <= 'z' for c in s):
        return False
    if len(t) != 3 + 2 * q:
        return False
    for i in range(q):
        l = int(t[3 + 2 * i])
        r = int(t[4 + 2 * i])
        if not (1 <= l <= r <= n):
            return False
    return True

def ref(inp):
    t = inp.split()
    n, q = int(t[0]), int(t[1])
    s = t[2]
    out = []
    for i in range(q):
        l = int(t[3 + 2 * i])
        r = int(t[4 + 2 * i])
        cnt = 0
        # 1-indexed positions p with l <= p <= r-1 and S_p == S_{p+1}
        for p in range(l, r):
            if s[p - 1] == s[p]:
                cnt += 1
        out.append(str(cnt))
    return "\n".join(out) + "\n"
